import { spawn } from "node:child_process";
import _kebabCase from "lodash.kebabcase";
/**
 * Converts an object of options to an array of command line arguments.
 *
 * @param options The options object.
 * @returns The command line arguments.
 */
function toArgs(obj) {
    return Object.entries(obj).flatMap(([key, value]) => {
        if (value === undefined)
            return [];
        if (Array.isArray(value))
            return [`--${_kebabCase(key)}`, value.join(",")];
        if (typeof value === "object" && value !== null) {
            return Object.entries(value).flatMap(([subKey, subValue]) => {
                if (subValue === undefined)
                    return [];
                const flag = `--${_kebabCase(`${key}.${subKey}`)}`;
                return [flag, Array.isArray(subValue) ? subValue.join(",") : subValue];
            });
        }
        const flag = `--${_kebabCase(key)}`;
        if (value === false)
            return [];
        if (value === true)
            return [flag];
        const stringified = value.toString();
        if (stringified === "")
            return [flag];
        return [flag, stringified];
    });
}
export const spawnAnvil = async (args) => {
    let started = false;
    let port = args.port ?? 0;
    const stop = await new Promise((resolve, reject) => {
        const subprocess = spawn("anvil", toArgs({ ...args, port }));
        subprocess.stdout.on("data", (data) => {
            const dataStr = data.toString();
            const listenMatch = dataStr.match(/Listening on 127.0.0.1:(\d+)/);
            if (listenMatch)
                port = Number.parseInt(listenMatch[1], 10);
            // console.debug(`[port ${port || "??"}] ${dataStr}`);
            if (listenMatch) {
                started = true;
                resolve(() => subprocess.kill("SIGINT"));
            }
        });
        subprocess.stderr.on("data", (data) => {
            const message = `[port ${port || "??"}] ${data.toString()}`;
            if (!started)
                reject(message);
            else
                console.warn(message);
        });
    });
    return {
        rpcUrl: `http://localhost:${port}`,
        stop,
    };
};
